using System;using System.IO;using System.Linq;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class UgoPaper {const string Folder=@"C:\Users\user\Desktop\02_Справочники_CAD_Revit\odnolineyka\_Разработка\ugo";[CommandMethod("CODEXUGOTOPAPER")]public void Run(){try{var doc=AcApp.DocumentManager.MdiActiveDocument;var db=doc.Database;ObjectId paperId;ObjectId[] ids;using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);var model=(BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);ids=model.Cast<ObjectId>().ToArray();var dict=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);paperId=((Layout)tr.GetObject(dict.GetAt("УГО"),OpenMode.ForRead)).BlockTableRecordId;}if(ids.Length!=19)throw new System.Exception("Expected 19 entities");var map=new IdMapping();db.DeepCloneObjects(new ObjectIdCollection(ids),paperId,map,false);using(var tr=db.TransactionManager.StartTransaction()){foreach(var id in ids){var e=(Entity)tr.GetObject(map[id].Value,OpenMode.ForWrite);e.TransformBy(Matrix3d.Displacement(new Vector3d(-1050,312.39071459069973,0)));e.Visible=true;var l=(LayerTableRecord)tr.GetObject(e.LayerId,OpenMode.ForWrite);l.IsOff=false;if(l.IsFrozen)l.IsFrozen=false;l.IsPlottable=true;((Entity)tr.GetObject(id,OpenMode.ForWrite)).Erase();}var paper=(BlockTableRecord)tr.GetObject(paperId,OpenMode.ForRead);foreach(ObjectId id in paper)if(tr.GetObject(id,OpenMode.ForRead) is Viewport v){v.UpgradeOpen();if(v.Number!=1)v.Erase();else v.Layer="Defpoints";}tr.Commit();}File.WriteAllText(Path.Combine(Folder,"paper_ok.txt"),"19 legend entities moved into paper space");}catch(System.Exception ex){File.WriteAllText(Path.Combine(Folder,"paper_error2.txt"),ex.ToString());}}}